# hypothesis: decorators built on ParamSpec and Concatenate keep the remaining parameters, including the bound self of a method, and a wrong argument type is rejected statically and raises TypeError at runtime.
from collections.abc import Callable
from typing import Concatenate, reveal_type


def logged[**P, R](fn: Callable[P, R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn(*args, **kwargs)
    return inner


def with_conn[**P, R](fn: Callable[Concatenate[str, P], R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return fn('main', *args, **kwargs)
    return inner


@with_conn
def count(conn: str, table: str, limit: int = 3) -> list[str]:
    return [f'{conn}.{table}'] * limit


class Repo:
    @logged
    def find(self, key: str) -> int:
        return len(key)


reveal_type(count)
reveal_type(Repo().find)
print(count('users', limit=2), Repo().find('abc'))

try:
    count('users', limit='many')  # expect-error: limit must be int
except TypeError as exc:
    print('runtime:', type(exc).__name__)

try:
    Repo().find(1)  # expect-error: key must be str
except TypeError as exc:
    print('runtime:', type(exc).__name__)
